class User {
  final String name;
  final int? age;

  const User({required this.name, this.age});
}

Future<List<Post>> fetchPosts() async {
  final res = await http.get(Uri.parse('$baseUrl/posts'));
  final data = jsonDecode(res.body) as List;
  return data.map((e) => Post.fromJson(e)).toList();
}

