Stream<int> countdown(int from) async* {
  for (var i = from; i >= 0; i--) {
    yield i;
  }
}

class Counter extends ChangeNotifier {
  int _count = 0;
  int get count => _count;
  void inc() { _count++; notifyListeners(); }
}
